def is_composite(n):
    if n <= 3:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return True
    return False

def can_be_expressed_as_sum(n):
    for k in range(1, n // 42 + 2):
        for c in range(4, n - 42 * k + 1, 2):
